/**
 * <div id="mongodb-bson-packedarray.fromjson" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\PackedArray::fromJSON</h1>  <p class="verinfo">(mongodb &gt;=1.20.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\PackedArray::fromJSON</span> — <span class="dc-title">Construct a new BSON array instance from a JSON string</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-packedarray.fromjson-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">static</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::fromJSON</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$json</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="type MongoDB\BSON\PackedArray" style="color:#EAB766">MongoDB\BSON\PackedArray</a></span></div>  <p class="simpara">   Converts an   <a href="https://www.mongodb.com/docs/manual/reference/mongodb-extended-json/" class="link external">»&nbsp;extended JSON</a>   string to its BSON representation.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-packedarray.fromjson-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">json</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      JSON value to be converted.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-packedarray.fromjson-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a new <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="classname">MongoDB\BSON\PackedArray</a></span> instance.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-packedarray.fromjson-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>    Throws    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-unexpectedvalueexception.php" class="classname">MongoDB\Driver\Exception\UnexpectedValueException</a></span> if    the JSON value cannot be converted to a BSON array (e.g. due to a syntax    error).   </li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-packedarray.fromjson-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::fromJSON()</strong></span> example</strong></p>   <div class="example-contents">    <div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$json </span><span style="color: #007700">= </span><span style="color: #DD0000">'[ "foo", { "\$numberInt" : "123" }, { "\$numberLong" : "4294967295" }, { "\$oid" : "56315a7c6118fd1b920270b1" } ]'</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$packedArray </span><span style="color: #007700">= </span><span style="color: #9876AA">MongoDB\BSON\PackedArray</span><span style="color: #007700">::</span><span style="color: #9876AA">fromJSON</span><span style="color: #007700">(</span><span style="color: #9876AA">\$json</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$packedArray</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;">    <div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\BSON\PackedArray)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["data"]=&gt;<br>&nbsp;&nbsp;string(68)&nbsp;"MQAAAAIwAAQAAABmb28AEDEAewAAABIyAP////8AAAAABzMAVjFafGEY/RuSAnCxAA=="<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;array(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(3)&nbsp;"foo"<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(123)<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(4294967295)<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;object(MongoDB\BSON\ObjectId)#2&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;string(24)&nbsp;"56315a7c6118fd1b920270b1"<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-packedarray.fromjson-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\PackedArray::fromPHP()} - Construct a new BSON array instance from PHP data</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/mongodb-extended-json/" class="link external">»&nbsp;MongoDB Extended JSON</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public static function fromJSON(string $json): PackedArray {}

/**
