/**
 * <div id="mongodb-bson-packedarray.tocanonicalextendedjson" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\PackedArray::toCanonicalExtendedJSON</h1>  <p class="verinfo">(mongodb &gt;=1.20.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\PackedArray::toCanonicalExtendedJSON</span> — <span class="dc-title">Returns the Canonical Extended JSON representation of the BSON array</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-packedarray.tocanonicalextendedjson-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::toCanonicalExtendedJSON</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Converts the BSON array to its   <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#canonical-extended-json-example" class="link external">»&nbsp;Canonical Extended JSON</a>   representation. The canonical format prefers type fidelity at the expense of   concise output and is most suited for producing output that can be converted   back to BSON without any loss of type information (e.g. numeric types will   remain differentiated).  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-packedarray.tocanonicalextendedjson-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-packedarray.tocanonicalextendedjson-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a string containing the   <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#canonical-extended-json-example" class="link external">»&nbsp;Canonical Extended JSON</a>   representation of the BSON array.  </p> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-packedarray.tocanonicalextendedjson-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::toCanonicalExtendedJSON()</strong></span> example</strong></p>   <div class="example-contents">    <div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$array </span><span style="color: #007700">= [<br>    </span><span style="color: #DD0000">'foo'</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">123</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">4294967295</span><span style="color: #007700">,<br>    new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">(</span><span style="color: #DD0000">'56315a7c6118fd1b920270b1'</span><span style="color: #007700">),<br>];<br><br></span><span style="color: #9876AA">\$packedArray </span><span style="color: #007700">= </span><span style="color: #9876AA">MongoDB\BSON\PackedArray</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$array</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$packedArray</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toCanonicalExtendedJSON</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;">    <div class="examplescode"><blockquote style="border:1px gray solid;">[&nbsp;"foo",&nbsp;{&nbsp;"\$numberInt"&nbsp;:&nbsp;"123"&nbsp;},&nbsp;{&nbsp;"\$numberLong"&nbsp;:&nbsp;"4294967295"&nbsp;},&nbsp;{&nbsp;"\$oid"&nbsp;:&nbsp;"56315a7c6118fd1b920270b1"&nbsp;}&nbsp;]</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-packedarray.tocanonicalextendedjson-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\PackedArray::fromJSON()} - Construct a new BSON array instance from a JSON string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\PackedArray::toRelaxedExtendedJSON()} - Returns the Relaxed Extended JSON representation of the BSON array</span></li>   <li><span class="function">{@link MongoDB\BSON\toCanonicalExtendedJSON()} - Returns the Canonical Extended JSON representation of a BSON value</span></li>   <li><a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md" class="link external">»&nbsp;Extended JSON Specification</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public function toCanonicalExtendedJSON(): string {}

/**
 * <div id="mongodb-bson-packedarray.torelaxedextendedjson" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\PackedArray::toRelaxedExtendedJSON</h1>  <p class="verinfo">(mongodb &gt;=1.20.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\PackedArray::toRelaxedExtendedJSON</span> — <span class="dc-title">Returns the Relaxed Extended JSON representation of the BSON array</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-packedarray.torelaxedextendedjson-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::toRelaxedExtendedJSON</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Converts the BSON array to its   <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#relaxed-extended-json-example" class="link external">»&nbsp;Relaxed Extended JSON</a>   representation. The relaxed format prefers use of JSON type primitives at the   expense of type fidelity and is most suited for producing output that can be   easily consumed by web APIs and humans.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-packedarray.torelaxedextendedjson-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-packedarray.torelaxedextendedjson-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a string containing the   <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#relaxed-extended-json-example" class="link external">»&nbsp;Relaxed Extended JSON</a>   representation of the BSON array.  </p> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-packedarray.torelaxedextendedjson-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::toRelaxedExtendedJSON()</strong></span> example</strong></p>   <div class="example-contents">    <div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$array </span><span style="color: #007700">= [<br>    </span><span style="color: #DD0000">'foo'</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">123</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">4294967295</span><span style="color: #007700">,<br>    new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">(</span><span style="color: #DD0000">'56315a7c6118fd1b920270b1'</span><span style="color: #007700">),<br>];<br><br></span><span style="color: #9876AA">\$packedArray </span><span style="color: #007700">= </span><span style="color: #9876AA">MongoDB\BSON\PackedArray</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$array</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$packedArray</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;">    <div class="examplescode"><blockquote style="border:1px gray solid;">[&nbsp;"foo",&nbsp;123,&nbsp;4294967295,&nbsp;{&nbsp;"\$oid"&nbsp;:&nbsp;"56315a7c6118fd1b920270b1"&nbsp;}&nbsp;]</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-packedarray.torelaxedextendedjson-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\PackedArray::fromJSON()} - Construct a new BSON array instance from a JSON string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\PackedArray::toCanonicalExtendedJSON()} - Returns the Canonical Extended JSON representation of the BSON array</span></li>   <li><span class="function">{@link MongoDB\BSON\toRelaxedExtendedJSON()} - Returns the Relaxed Extended JSON representation of a BSON value</span></li>   <li><a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md" class="link external">»&nbsp;Extended JSON Specification</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public function toRelaxedExtendedJSON(): string {}

/**
 * <div id="mongodb-bson-packedarray.offsetexists" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\PackedArray::offsetExists</h1>  <p class="verinfo">(mongodb &gt;=1.17.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\PackedArray::offsetExists</span> — <span class="dc-title">Returns whether a index is present in the array</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-packedarray.offsetexists-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::offsetExists</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-packedarray.offsetexists-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">key</span></dt>     <dd>      <span class="simpara">       The index to look for in the array.      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-packedarray.offsetexists-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the index is present in the array and <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-packedarray.offsetexists-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link ArrayAccess::offsetExists()} - 检查一个偏移位置是否存在</span></li>    <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\PackedArray::has()} - Returns whether a index is present in the array</span></li>   </ul>   </div></div>
 */
    public function offsetExists(mixed $offset): bool {}

/**
 * <div id="mongodb-bson-packedarray.offsetget" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\PackedArray::offsetGet</h1>  <p class="verinfo">(mongodb &gt;=1.17.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\PackedArray::offsetGet</span> — <span class="dc-title">Returns the value of an index in the array</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-packedarray.offsetget-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::offsetGet</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-packedarray.offsetget-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">key</span></dt>     <dd>      <span class="simpara">       The index to retrieve from the array. Only <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> is supported.      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-packedarray.offsetget-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the value associated with the given index. If the index is not   present in the array, an exception is thrown.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    When encountering a value encoded as 64-bit integer in the BSON array,    the return value of this method will be a    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span> instance.   </span>  </p></blockquote> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-packedarray.offsetget-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> if the index is not present in the array.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-packedarray.offsetget-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link ArrayAccess::offsetGet()} - 获取一个偏移位置的值</span></li>    <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\PackedArray::get()} - Returns the value of an index in the array</span></li>   </ul>   </div></div>
 */
    public function offsetGet(mixed $offset): mixed {}

/**
 * <div id="mongodb-bson-packedarray.offsetset" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\PackedArray::offsetSet</h1>  <p class="verinfo">(mongodb &gt;=1.17.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\PackedArray::offsetSet</span> — <span class="dc-title">Implementation of <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.arrayaccess.php" class="type ArrayAccess" style="color:#EAB766">ArrayAccess</a></span></span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-packedarray.offsetset-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::offsetSet</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Sets the value at the specified <span class="parameter" style="color:#3A95FF">key</span> to <span class="parameter" style="color:#3A95FF">value</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-packedarray.offsetset-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">key</span></dt>     <dd>      <span class="simpara">       The index being set.      </span>     </dd>             <dt><span class="parameter" style="color:#3A95FF">value</span></dt>     <dd>      <span class="simpara">       The new value for the <span class="parameter" style="color:#3A95FF">key</span>.      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-packedarray.offsetset-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-packedarray.offsetset-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Always throws a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-logicexception.php" class="classname">MongoDB\Driver\Exception\LogicException</a></span>.</li>  </ul> </div></div>
 */
    public function offsetSet(mixed $offset, mixed $value): void {}

