 * <div id="mongodb-bson-packedarray.offsetunset" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\PackedArray::offsetUnset</h1>  <p class="verinfo">(mongodb &gt;=1.17.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\PackedArray::offsetUnset</span> — <span class="dc-title">Implementation of <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.arrayaccess.php" class="type ArrayAccess" style="color:#EAB766">ArrayAccess</a></span></span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-packedarray.offsetunset-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\PackedArray::offsetUnset</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Unsets the value at the specified index.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-packedarray.offsetunset-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">key</span></dt>     <dd>      <span class="simpara">       The index being unset.      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-packedarray.offsetunset-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-packedarray.offsetunset-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Always throws a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-logicexception.php" class="classname">MongoDB\Driver\Exception\LogicException</a></span>.</li>  </ul> </div></div>
 */
    public function offsetUnset(mixed $offset): void {}

